  ('clipboard-api', 'javascript', 'browser-apis', 'Clipboard API', 'clipboard-api', 'FileText', 'Intermediate', 'Read from and write to the system clipboard using the modern async Clipboard API — copy text, images, and rich content programmatically.', null, 'The Clipboard API provides async methods to read from and write to the system clipboard. navigator.clipboard.writeText() copies text, and navigator.clipboard.readText() reads it. For rich content (images, HTML), use write() and read() with ClipboardItem objects. It requires user permission and a secure context (HTTPS). The API is Promise-based, unlike the older document.execCommand(''copy''). Writing usually works without explicit permission; reading always requires it. The API is designed to be safe — it can''t silently read clipboard contents without user interaction.', 'The Clipboard API is like a shared notepad between apps. You can write a note on it (writeText) or read what someone else wrote (readText). But there''s a security guard — before you can READ someone else''s note, you need permission. Writing is usually allowed because you''re sharing YOUR content. The notepad can hold text, images, or even formatted documents (ClipboardItem).', '["navigator.clipboard.writeText(text) — copy text to clipboard","navigator.clipboard.readText() — read text from clipboard","navigator.clipboard.write() — copy rich content (images, HTML)","navigator.clipboard.read() — read rich content","Async/Promise-based API","Requires HTTPS (secure context)","Reading requires user permission; writing usually doesn''t","ClipboardItem for handling multiple MIME types"]', null, null, '// ===== Clipboard API =====

// ── Copy text ───────────────────────────────────
console.log("--- Copy Text ---");

async function copyText() {
  try {
    await navigator.clipboard.writeText("Hello, World!");
    console.log("Text copied to clipboard!");
  } catch (err) {
    console.log("Copy failed:", err.message);
  }
}

// ── Read text ───────────────────────────────────
console.log("\n--- Read Text ---");

async function pasteText() {
  try {
    const text = await navigator.clipboard.readText();
    console.log("Clipboard contains:", text);
  } catch (err) {
    console.log("Read failed:", err.message);
  }
}

// ── Copy button pattern ─Γö────────────────────────
console.log("\n--- Copy Button Pattern ---");

function setupCopyButton(buttonEl, textToCopy) {
  buttonEl.addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(textToCopy);
      buttonEl.textContent = "Copied!";
      setTimeout(() => {
        buttonEl.textContent = "Copy";
      }, 2000);
    } catch (err) {
      buttonEl.textContent = "Failed";
    }
  });
  console.log("Copy button ready!");
}

// ── Copy rich content (HTML/images) ─────────────
console.log("\n--- Rich Content ---");

async function copyHTML() {
  const htmlBlob = new Blob(
    ["<b>Bold text</b> and <i>italic</i>"],
    { type: "text/html" }
  );
  const textBlob = new Blob(
    ["Bold text and italic"],
    { type: "text/plain" }
  );

  const item = new ClipboardItem({
    "text/html": htmlBlob,
    "text/plain": textBlob,
  });

  await navigator.clipboard.write([item]);
  console.log("Rich content copied!");
}

console.log("Functions defined: copyText, pasteText, copyHTML");
